<template>
<view class="page">
  <template v-if="loading"><view class="state">正在生成本关题目...</view></template>
  <template v-else-if="!finished&&current">
    <view class="head"><text class="eyebrow">第 {{ level.levelNo }} 关</text><text class="title">{{ level.title }}</text><view class="progress"><view :style="{width:progress+'%'}"></view></view><view class="meta"><text>{{ index+1 }}/{{ questions.length }}</text><text>答对 {{ correctCount }} 题</text></view></view>
    <view class="card"><text class="type">{{ typeName }}</text><text class="prompt">{{ current.prompt }}</text><text v-if="current.translation&&current.type!=='word'" class="translation">{{ current.translation }}</text><view v-if="current.audioText" class="play" @click="playAudio">🔊 播放发音</view><view class="options"><view v-for="option in current.options" :key="option" class="option" :class="optionClass(option)" @click="choose(option)"><text>{{ option }}</text></view></view><view v-if="answered" class="feedback" :class="{ right: isCorrect, wrong: !isCorrect }"><text class="feedback-title">{{ isCorrect ? '回答正确' : '回答错误' }}</text><text>{{ current.explanation }}</text></view></view>
  </template>
  <view v-else-if="finished" class="result-card"><view class="result-icon">{{ result.passed ? '🎉' : '🧩' }}</view><text class="result-title">{{ result.passed ? '闯关成功' : '还差一点' }}</text><text class="score">{{ result.score }}<text>分</text></text><text class="result-desc">答对 {{ result.correct }}/{{ result.total }} 题 · 通关要求 {{ passScore }} 分</text><view class="stars">{{ resultStars }}</view><view v-if="result.wrong&&result.wrong.length" class="weak"><text class="weak-title">本轮薄弱内容</text><text v-for="item in result.wrong.slice(0,3)" :key="item.id">• {{ item.prompt }}</text></view><button v-if="result.passed&&result.next" class="primary" @click="goNext">继续下一关</button><button v-else class="primary" @click="restart">重新挑战</button><button class="secondary" @click="goMap">返回成长地图</button></view>
</view>
</template>
<script>
import { request, getSettings } from '@/utils/api.js';
import { playTts, clearTtsQueue } from '@/utils/tts-player.js';
import { playAnswerFeedback } from '@/utils/answer-feedback.js';
export default{data(){return{levelId:'',loading:true,level:{},questions:[],index:0,answered:false,selected:'',isCorrect:false,answers:[],finished:false,result:{},passScore:80,audio:null,advanceTimer:null,audioTimer:null,audioRequestId:0,autoPlay:false,accent:0}},computed:{current(){return this.questions[this.index]},resultStars(){if(!this.result.passed)return '☆☆☆';return '★'.repeat(this.result.stars||0)+'☆'.repeat(3-(this.result.stars||0))},progress(){return this.questions.length?this.index*100/this.questions.length:0},correctCount(){return this.answers.filter(item=>item.correct).length},typeName(){return this.current?.type==='grammar'?'语法应用':(this.current?.type==='phonetic'?'音标训练':(this.current?.type==='listen'?'听音辨义':'单词理解'))}},onLoad(q){this.levelId=String(q.id||'');this.load()},onUnload(){clearTtsQueue();if(this.advanceTimer)clearTimeout(this.advanceTimer);if(this.audioTimer)clearTimeout(this.audioTimer)},methods:{async load(){this.loading=true;try{const [data,settings]=await Promise.all([request('/adventure-course/level/'+this.levelId+'/questions'),getSettings()]);this.autoPlay=Boolean(Number(settings?.auto_play||0));this.accent=Number(settings?.accent||0);this.level=data.level;this.questions=data.questions||[];this.passScore=data.passScore;this.index=0;this.answers=[];this.finished=false;this.answered=false;this.scheduleAutoPlay()}catch(e){uni.showModal({title:'无法开始关卡',content:e.message||'题目加载失败',showCancel:false,success:()=>uni.navigateBack()})}finally{this.loading=false}},choose(option){if(this.answered)return;this.selected=option;this.answered=true;this.isCorrect=option===this.current.answer;playAnswerFeedback(this.isCorrect);this.answers.push({id:this.current.id,type:this.current.type,prompt:this.current.prompt,userAnswer:option,answer:this.current.answer,explanation:this.current.explanation,correct:this.isCorrect});if(this.advanceTimer)clearTimeout(this.advanceTimer);this.advanceTimer=setTimeout(()=>{this.advanceTimer=null;this.next()},350)},optionClass(option){if(!this.answered)return '';if(option===this.current.answer)return 'correct';if(option===this.selected)return 'wrong';return 'dim'},async next(){if(!this.answered)return;if(this.index+1<this.questions.length){this.index++;this.answered=false;this.selected='';this.isCorrect=false;this.scheduleAutoPlay();return}uni.showLoading({title:'正在结算'});try{this.result=await request('/adventure-course/level/'+this.levelId+'/submit','POST',{answers:this.answers});this.finished=true}catch(e){uni.showToast({title:e.message||'结算失败',icon:'none'})}finally{uni.hideLoading()}},scheduleAutoPlay(){if(this.audioTimer)clearTimeout(this.audioTimer);if(!this.autoPlay||!this.current?.audioText)return;this.audioTimer=setTimeout(()=>{this.audioTimer=null;this.playAudio()},350)},playAudio(){if(!this.current?.audioText)return;playTts(this.current.audioText,3).catch(error=>{console.error('闯关语音播放失败:',error);uni.showToast({title:error?.message||'播放失败，请重试',icon:'none'})})},restart(){this.load()},goNext(){uni.redirectTo({url:'/pages/adventure/practice?id='+this.result.next})},goMap(){uni.redirectTo({url:'/pages/adventure/module?key='+this.result.moduleKey})}}}
</script>
<style>
.page{box-sizing:border-box;min-height:100vh;padding:24rpx 22rpx 50rpx;background:linear-gradient(180deg,#edf5f6,#f7f5f0 430rpx)}.head{text-align:center}.eyebrow{font-size:21rpx;font-weight:800;color:#0d9488}.title{display:block;margin-top:5rpx;font-size:40rpx;font-weight:900;color:#1f3a5f}.progress{height:10rpx;margin-top:23rpx;border-radius:8rpx;background:#dfe7ea;overflow:hidden}.progress view{height:100%;border-radius:8rpx;background:#159e92}.meta{display:flex;justify-content:space-between;margin-top:9rpx;font-size:21rpx;color:#7f8d98}.card{margin-top:24rpx;padding:29rpx 24rpx;border-radius:25rpx;background:#fff;box-shadow:0 8rpx 25rpx rgba(31,58,95,.08)}.type{font-size:21rpx;font-weight:800;color:#0d9488}.prompt{display:block;margin-top:22rpx;font-size:34rpx;font-weight:800;line-height:1.5;color:#213f61}.translation{display:block;margin-top:10rpx;padding:13rpx 16rpx;border-radius:12rpx;background:#f3f7f8;font-size:22rpx;color:#73838e}.play{display:inline-block;margin-top:18rpx;padding:13rpx 20rpx;border-radius:25rpx;background:#e5f6f2;color:#0d9488;font-size:22rpx}.options{margin-top:24rpx}.option{margin-top:13rpx;padding:23rpx 20rpx;border:2rpx solid #e6ebee;border-radius:16rpx;background:#fff;font-size:27rpx;color:#344c61}.option.correct{border-color:#40b982;background:#edfaf3;color:#17865d}.option.wrong{border-color:#e36b64;background:#fff1ef;color:#c94e47}.option.dim{opacity:.55}.feedback{margin-top:20rpx;padding:18rpx;border-radius:15rpx;font-size:22rpx;line-height:1.5}.feedback text{display:block}.feedback-title{margin-bottom:4rpx;font-size:25rpx;font-weight:900}.feedback.right{background:#edf9f4;color:#16845f}.feedback.wrong{background:#fff2ef;color:#c9534c}.next,.primary,.secondary{height:82rpx;line-height:82rpx;margin-top:22rpx;border:0;border-radius:17rpx;background:#1f3a5f;color:#fff;font-size:28rpx;font-weight:800}.next:after,.primary:after,.secondary:after{border:0}.next[disabled]{background:#dce2e7;color:#96a0a9}.state{padding:180rpx 0;text-align:center;color:#7f8d98}.result-card{margin-top:35rpx;padding:42rpx 28rpx;border-radius:28rpx;background:#fff;text-align:center;box-shadow:0 9rpx 28rpx rgba(31,58,95,.1)}.result-icon{font-size:73rpx}.result-title{display:block;margin-top:11rpx;font-size:39rpx;font-weight:900;color:#213f61}.score{display:block;margin-top:15rpx;font-size:70rpx;font-weight:900;color:#0d9488}.score text{font-size:25rpx}.result-desc{display:block;margin-top:5rpx;font-size:22rpx;color:#81909b}.stars{margin-top:17rpx;font-size:42rpx;letter-spacing:7rpx;color:#d6a53a}.weak{margin-top:25rpx;padding:20rpx;border-radius:18rpx;background:#fff5f2;text-align:left;color:#7b5a54}.weak text{display:block;margin-top:7rpx;font-size:21rpx;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.weak-title{font-size:25rpx!important;font-weight:900;color:#c7544b}.secondary{margin-top:13rpx;background:#edf2f5;color:#526a7d}
</style>
